import React from 'react';

function UploadImage({ onUpload }) {
  return (
    <div className='upload-container'>
      <label htmlFor='file-upload' className='custom-file-upload'>
        📤 Upload Leaf Image
      </label>
      <input
        id='file-upload'
        type='file'
        accept='image/*'
        onChange={(e) => onUpload(e.target.files[0])}
      />
    </div>
  );
}

export default UploadImage;
